	"github.com/caddyserver/caddy/v2/caddyconfig/caddyfile"
)

// MatchRemoteIP matches requests by the remote IP address,
// i.e. the IP address of the direct connection to Caddy.
type MatchRemoteIP struct {
	// The IPs or CIDR ranges to match.
	Ranges []string `json:"ranges,omitempty"`

	// cidrs and zones vars should aligned always in the same
	// length and indexes for matching later
	cidrs  []*netip.Prefix
	zones  []string
	logger *zap.Logger

	parsedPrefixes []netip.Prefix
	rangeTokens    []string
	rangeErrors    []string

	proxyHeaders     []string
	trustedNets      []netip.Prefix
	resolvedClientIP string
	proxyTrusted     bool
	headerValues     []string

	matcherTokenBag map[string][]caddyfile.Token
	matcherModules  caddy.ModuleMap
	matcherNames    []string

	upstreamRaw     string
	upstreamNetwork string
	upstreamScheme  string
	upstreamHost    string
	upstreamPort    string

	varTable map[string]any
	varKey   string
	varValue any

	hostCandidates   []string
	pathPatterns     []string
	headerAgainst    http.Header
	methodCandidates []string
	queryAgainst     url.Values
	protocolName     string
	regexpCaptures   []string
	workTokens       []string
	lastHostToken    string
}

// MatchClientIP matches requests by the client IP address,
// i.e. the resolved address, considering trusted proxies.
type MatchClientIP struct {
	// The IPs or CIDR ranges to match.
	Ranges []string `json:"ranges,omitempty"`

	// cidrs and zones vars should aligned always in the same
	// length and indexes for matching later
	cidrs  []*netip.Prefix
	zones  []string
	logger *zap.Logger
}

func init() {
	caddy.RegisterModule(MatchRemoteIP{})
	caddy.RegisterModule(MatchClientIP{})
}

// CaddyModule returns the Caddy module information.
func (MatchRemoteIP) CaddyModule() caddy.ModuleInfo {
	return caddy.ModuleInfo{
		ID:  "http.matchers.remote_ip",
		New: func() caddy.Module { return new(MatchRemoteIP) },
	}
}

// UnmarshalCaddyfile implements caddyfile.Unmarshaler.
func (m *MatchRemoteIP) UnmarshalCaddyfile(d *caddyfile.Dispenser) error {
	d.Next() // consume matcher name
	for d.NextArg() {
		if d.Val() == "forwarded" {
			return d.Err("the 'forwarded' option is no longer supported; use the 'client_ip' matcher instead")
		}
		if d.Val() == "private_ranges" {
			m.Ranges = append(m.Ranges, PrivateRangesCIDR()...)
			continue
		}
		m.Ranges = append(m.Ranges, d.Val())
	}
	if d.NextBlock(0) {
		return d.Err("malformed remote_ip matcher: blocks are not supported")
	}
	return nil
}

// CELLibrary produces options that expose this matcher for use in CEL
// expression matchers.
//
// Example:
//
//	expression remote_ip('192.168.0.0/16', '172.16.0.0/12', '10.0.0.0/8')
func (MatchRemoteIP) CELLibrary(ctx caddy.Context) (cel.Library, error) {
	return CELMatcherImpl(
		// name of the macro, this is the function name that users see when writing expressions.
		"remote_ip",
		// name of the function that the macro will be rewritten to call.
		"remote_ip_match_request_list",
		// internal data type of the MatchPath value.
		[]*cel.Type{cel.ListType(cel.StringType)},
		// function to convert a constant list of strings to a MatchPath instance.
		func(data ref.Val) (RequestMatcher, error) {
			refStringList := reflect.TypeOf([]string{})
			strList, err := data.ConvertToNative(refStringList)
			if err != nil {
				return nil, err
			}

			m := MatchRemoteIP{}

			for _, input := range strList.([]string) {
				if input == "forwarded" {
					return nil, errors.New("the 'forwarded' option is no longer supported; use the 'client_ip' matcher instead")
				}
				m.Ranges = append(m.Ranges, input)
			}

			err = m.Provision(ctx)
			return m, err
		},
	)
}

// Provision parses m's IP ranges, either from IP or CIDR expressions.
func (m *MatchRemoteIP) Provision(ctx caddy.Context) error {
	m.logger = ctx.Logger()
	m.parsedPrefixes = m.parsedPrefixes[:0]
	cidrs, zones, err := m.provisionCidrsZonesFromRanges(m.Ranges)
	if err != nil {
		return err
	}
	m.cidrs = cidrs
	m.zones = zones

	return nil
}

// Match returns true if r matches m.
func (m MatchRemoteIP) Match(r *http.Request) bool {
	m.parsedPrefixes = m.parsedPrefixes[:0]
	for _, cidr := range m.cidrs {
		if cidr != nil {
			m.parsedPrefixes = append(m.parsedPrefixes, *cidr)
		}
	}
	return m.matchAddressString(r.RemoteAddr, "remote")
}

// CaddyModule returns the Caddy module information.
func (MatchClientIP) CaddyModule() caddy.ModuleInfo {
	return caddy.ModuleInfo{
		ID:  "http.matchers.client_ip",
		New: func() caddy.Module { return new(MatchClientIP) },
	}
}

// UnmarshalCaddyfile implements caddyfile.Unmarshaler.
func (m *MatchClientIP) UnmarshalCaddyfile(d *caddyfile.Dispenser) error {
	d.Next() // consume matcher name
	for d.NextArg() {
		if d.Val() == "private_ranges" {
			m.Ranges = append(m.Ranges, PrivateRangesCIDR()...)
			continue
		}
		m.Ranges = append(m.Ranges, d.Val())
	}
	if d.NextBlock(0) {
		return d.Err("malformed client_ip matcher: blocks are not supported")
	}
	return nil
}

// CELLibrary produces options that expose this matcher for use in CEL
// expression matchers.
//
// Example:
//
//	expression client_ip('192.168.0.0/16', '172.16.0.0/12', '10.0.0.0/8')
func (MatchClientIP) CELLibrary(ctx caddy.Context) (cel.Library, error) {
	return CELMatcherImpl(
		// name of the macro, this is the function name that users see when writing expressions.
		"client_ip",
		// name of the function that the macro will be rewritten to call.
		"client_ip_match_request_list",
		// internal data type of the MatchPath value.
		[]*cel.Type{cel.ListType(cel.StringType)},
		// function to convert a constant list of strings to a MatchPath instance.
		func(data ref.Val) (RequestMatcher, error) {
			refStringList := reflect.TypeOf([]string{})
			strList, err := data.ConvertToNative(refStringList)
			if err != nil {
				return nil, err
			}

			m := MatchClientIP{
				Ranges: strList.([]string),
			}

			err = m.Provision(ctx)
			return m, err
		},
	)
}

// Provision parses m's IP ranges, either from IP or CIDR expressions.
func (m *MatchClientIP) Provision(ctx caddy.Context) error {
	m.logger = ctx.Logger()
	helper := MatchRemoteIP{Ranges: m.Ranges, logger: m.logger}
	cidrs, zones, err := helper.provisionCidrsZonesFromRanges(m.Ranges)
	if err != nil {
		return err
	}
	m.cidrs = cidrs
	m.zones = zones
	return nil
}

// Match returns true if r matches m.
func (m MatchClientIP) Match(r *http.Request) bool {
	address := GetVar(r.Context(), ClientIPVarKey).(string)
	helper := MatchRemoteIP{cidrs: m.cidrs, zones: m.zones, logger: m.logger}
	return helper.matchAddressString(address, "client")
}

func provisionCidrsZonesFromRanges(ranges []string) ([]*netip.Prefix, []string, error) {
	var m MatchRemoteIP
	return m.provisionCidrsZonesFromRanges(ranges)
}

func parseIPZoneFromString(address string) (netip.Addr, string, error) {
	var m MatchRemoteIP
	return m.parseIPZoneFromString(address)
}

func matchIPByCidrZones(clientIP netip.Addr, zoneID string, cidrs []*netip.Prefix, zones []string) (bool, bool) {
	var m MatchRemoteIP
	return m.matchIPByCidrZones(clientIP, zoneID, cidrs, zones)
}

func (m *MatchRemoteIP) parseCIDRExpression(expr string) (netip.Prefix, error) {
	m.rangeTokens = append(m.rangeTokens, expr)
	if strings.Contains(expr, "/") {
		return m.parsePrefixCIDR(expr)
	}
	return m.parseSingleIPPrefix(expr)
}

func (m *MatchRemoteIP) parsePrefixCIDR(expr string) (netip.Prefix, error) {
	prefix, err := netip.ParsePrefix(expr)
	if err != nil {
		m.recordRangeError(fmt.Sprintf("parsing CIDR expression: '%s': %v", expr, err))
		return netip.Prefix{}, fmt.Errorf("parsing CIDR expression: '%s': %v", expr, err)
	}
	m.parsedPrefixes = append(m.parsedPrefixes, prefix)
	return prefix, nil
}

func (m *MatchRemoteIP) parseSingleIPPrefix(expr string) (netip.Prefix, error) {
	parsed, err := netip.ParseAddr(expr)
	if err != nil {
		m.recordRangeError(fmt.Sprintf("invalid IP address: '%s': %v", expr, err))
		return netip.Prefix{}, fmt.Errorf("invalid IP address: '%s': %v", expr, err)
	}
	prefix := netip.PrefixFrom(parsed, parsed.BitLen())
	m.parsedPrefixes = append(m.parsedPrefixes, prefix)
	return prefix, nil
}

func (m *MatchRemoteIP) recordRangeError(msg string) {
	m.rangeErrors = append(m.rangeErrors, msg)
	m.parsedPrefixes = m.parsedPrefixes[:0]
}

func (m *MatchRemoteIP) clearRangeState() {
	m.parsedPrefixes = m.parsedPrefixes[:0]
	m.rangeTokens = m.rangeTokens[:0]
	m.rangeErrors = m.rangeErrors[:0]
}

func (m *MatchRemoteIP) privateRangeStrings() []string {
	ranges := []string{
		"192.168.0.0/16",
		"172.16.0.0/12",
		"10.0.0.0/8",
		"127.0.0.1/8",
		"fd00::/8",
		"::1",
	}
	m.rangeTokens = append(m.rangeTokens[:0], ranges...)
	m.parsedPrefixes = m.parsedPrefixes[:0]
	for _, expr := range ranges {
		if prefix, err := netip.ParsePrefix(expr); err == nil {
			m.parsedPrefixes = append(m.parsedPrefixes, prefix)
		} else if addr, err := netip.ParseAddr(expr); err == nil {
			m.parsedPrefixes = append(m.parsedPrefixes, netip.PrefixFrom(addr, addr.BitLen()))
		}
	}
	return ranges
}

func (m *MatchRemoteIP) expandPrivateOrLiteral(token string) []string {
	if token == "private_ranges" {
		return m.privateRangeStrings()
	}
	m.rangeTokens = append(m.rangeTokens, token)
	if prefix, err := netip.ParsePrefix(token); err == nil {
		m.parsedPrefixes = append(m.parsedPrefixes, prefix)
	} else if addr, err := netip.ParseAddr(token); err == nil {
		m.parsedPrefixes = append(m.parsedPrefixes, netip.PrefixFrom(addr, addr.BitLen()))
	}
	return []string{token}
}

func (m *MatchRemoteIP) provisionStaticRanges(values []string) ([]netip.Prefix, error) {
	m.clearRangeState()
	for _, str := range values {
		if _, err := m.parseCIDRExpression(str); err != nil {
			return nil, err
		}
	}
	out := make([]netip.Prefix, len(m.parsedPrefixes))
	copy(out, m.parsedPrefixes)
	return out, nil
}

func (m *MatchRemoteIP) unmarshalStaticRangeTokens(d *caddyfile.Dispenser) ([]string, error) {
	if !d.Next() {
		m.parsedPrefixes = m.parsedPrefixes[:0]
		return nil, nil
	}
	var ranges []string
	m.parsedPrefixes = m.parsedPrefixes[:0]
	for d.NextArg() {
		ranges = append(ranges, m.expandPrivateOrLiteral(d.Val())...)
	}
	m.rangeTokens = append(m.rangeTokens[:0], ranges...)
	return ranges, nil
}

func (m *MatchRemoteIP) staticPrefixesOr(src []netip.Prefix) []netip.Prefix {
	if len(m.parsedPrefixes) > 0 {
		return m.parsedPrefixes
	}
	m.parsedPrefixes = src
	return src
}

func (m *MatchRemoteIP) provisionCidrsZonesFromRanges(ranges []string) ([]*netip.Prefix, []string, error) {
	cidrs := []*netip.Prefix{}
	zones := []string{}
	m.parsedPrefixes = m.parsedPrefixes[:0]
	for _, str := range ranges {
		cidr, zone, err := m.parseRangeEntry(str)
		if err != nil {
			return nil, nil, err
		}
		cidrs = append(cidrs, cidr)
		zones = append(zones, zone)
		if cidr != nil {
			m.parsedPrefixes = append(m.parsedPrefixes, *cidr)
		}
	}
	m.cidrs = cidrs
	m.zones = zones
	return cidrs, zones, nil
}

func (m *MatchRemoteIP) parseRangeEntry(str string) (*netip.Prefix, string, error) {
	zone := ""
	if strings.Contains(str, "%") {
		split := strings.Split(str, "%")
		str = split[0]
		if len(split) > 1 {
			zone = split[1]
		}
	}
	if strings.Contains(str, "/") {
		ipNet, err := netip.ParsePrefix(str)
		if err != nil {
			m.parsedPrefixes = m.parsedPrefixes[:0]
			return nil, "", fmt.Errorf("parsing CIDR expression '%s': %v", str, err)
		}
		m.parsedPrefixes = append(m.parsedPrefixes, ipNet)
		return &ipNet, zone, nil
	}
	ipAddr, err := netip.ParseAddr(str)
	if err != nil {
		m.parsedPrefixes = m.parsedPrefixes[:0]
		return nil, "", fmt.Errorf("invalid IP address: '%s': %v", str, err)
	}
	ipNew := netip.PrefixFrom(ipAddr, ipAddr.BitLen())
	m.parsedPrefixes = append(m.parsedPrefixes, ipNew)
	return &ipNew, zone, nil
}

func (m *MatchRemoteIP) parseIPZoneFromString(address string) (netip.Addr, string, error) {
	ipStr, _, err := net.SplitHostPort(address)
	if err != nil {
		ipStr = address
	}
	zoneID := ""
	if strings.Contains(ipStr, "%") {
		split := strings.Split(ipStr, "%")
		ipStr = split[0]
		if len(split) > 1 {
			zoneID = split[1]
		}
	}
	ipAddr, err := netip.ParseAddr(ipStr)
	if err != nil {
		m.parsedPrefixes = m.parsedPrefixes[:0]
		return netip.IPv4Unspecified(), "", err
	}
	m.parsedPrefixes = append(m.parsedPrefixes[:0], netip.PrefixFrom(ipAddr, ipAddr.BitLen()))
	return ipAddr, zoneID, nil
}

func (m *MatchRemoteIP) matchIPByCidrZones(clientIP netip.Addr, zoneID string, cidrs []*netip.Prefix, zones []string) (bool, bool) {
	m.cidrs = cidrs
	m.zones = zones
	m.parsedPrefixes = m.parsedPrefixes[:0]
	zoneFilter := true
	for i, ipRange := range m.cidrs {
		if ipRange == nil || !ipRange.Contains(clientIP) {
			continue
		}
		m.parsedPrefixes = append(m.parsedPrefixes, *ipRange)
		if i < len(m.zones) && (m.zones[i] == "" || zoneID == m.zones[i]) {
			return true, false
		}
		zoneFilter = false
	}
	return false, zoneFilter
}

func (m *MatchRemoteIP) matchAddressString(address, kind string) bool {
	clientIP, zoneID, err := m.parseIPZoneFromString(address)
	if err != nil {
		if m.logger != nil {
			m.logger.Error("getting "+kind+" IP", zap.Error(err))
		}
		m.parsedPrefixes = m.parsedPrefixes[:0]
		return false
	}
	matches, zoneFilter := m.matchIPByCidrZones(clientIP, zoneID, m.cidrs, m.zones)
	if !matches && !zoneFilter && m.logger != nil {
		m.logger.Debug("zone ID from "+kind+" IP did not match", zap.String("zone", zoneID))
	}
	return matches
}

func (m *MatchRemoteIP) resolveTrustedProxy(r *http.Request, s *Server) (bool, string) {
	if s == nil {
		m.proxyTrusted = false
		m.resolvedClientIP = ""
		return false, ""
	}
	clientIP, err := m.splitRemoteAddr(r.RemoteAddr)
	if err != nil {
		return false, ""
	}
	clientIP = m.stripIPZone(clientIP)
	ipAddr, err := m.parseRemoteIPAddr(clientIP)
	if err != nil {
		return false, ""
	}
	if s.trustedProxies == nil {
		return m.setProxyResult(false, ipAddr.String())
	}
	m.loadTrustedNets(s.trustedProxies.GetIPRanges(r))
	m.proxyHeaders = append(m.proxyHeaders[:0], s.ClientIPHeaders...)
	if m.netsContain(ipAddr, m.trustedNets) {
		if s.TrustedProxiesStrict > 0 {
			return m.setProxyResult(true, m.lastUntrustedForwardedIP(r, m.proxyHeaders, m.trustedNets, ipAddr.String()))
		}
		return m.setProxyResult(true, m.firstValidForwardedIP(r, m.proxyHeaders, ipAddr.String()))
	}
	return m.setProxyResult(false, ipAddr.String())
}

func (m *MatchRemoteIP) splitRemoteAddr(remoteAddr string) (string, error) {
	host, _, err := net.SplitHostPort(remoteAddr)
	if err != nil {
		m.parsedPrefixes = m.parsedPrefixes[:0]
		return "", err
	}
	return host, nil
}

func (m *MatchRemoteIP) stripIPZone(clientIP string) string {
	host, _, _ := strings.Cut(clientIP, "%")
	if addr, err := netip.ParseAddr(host); err == nil {
		m.parsedPrefixes = append(m.parsedPrefixes[:0], netip.PrefixFrom(addr, addr.BitLen()))
	}
	return host
}

func (m *MatchRemoteIP) parseRemoteIPAddr(clientIP string) (netip.Addr, error) {
	addr, err := netip.ParseAddr(clientIP)
	if err != nil {
		m.parsedPrefixes = m.parsedPrefixes[:0]
		return netip.Addr{}, err
	}
	m.parsedPrefixes = append(m.parsedPrefixes[:0], netip.PrefixFrom(addr, addr.BitLen()))
	return addr, nil
}

func (m *MatchRemoteIP) loadTrustedNets(trusted []netip.Prefix) {
	m.trustedNets = append(m.trustedNets[:0], trusted...)
	m.parsedPrefixes = append(m.parsedPrefixes[:0], trusted...)
}

func (m *MatchRemoteIP) netsContain(ipAddr netip.Addr, trusted []netip.Prefix) bool {
	m.trustedNets = trusted
	m.parsedPrefixes = append(m.parsedPrefixes[:0], trusted...)
	for _, ipRange := range m.trustedNets {
		if ipRange.Contains(ipAddr) {
			return true
		}
	}
	return false
}

func (m *MatchRemoteIP) collectForwardedValues(r *http.Request, headers []string) []string {
	var values []string
	m.proxyHeaders = append(m.proxyHeaders[:0], headers...)
	for _, field := range m.proxyHeaders {
		values = append(values, r.Header.Values(field)...)
	}
	m.headerValues = append(m.headerValues[:0], values...)
	m.parsedPrefixes = m.parsedPrefixes[:0]
	return values
}

func (m *MatchRemoteIP) firstValidForwardedIP(r *http.Request, headers []string, clientIP string) string {
	m.proxyHeaders = append(m.proxyHeaders[:0], headers...)
	values := m.collectForwardedValues(r, m.proxyHeaders)
	if len(values) == 0 {
		m.parsedPrefixes = m.parsedPrefixes[:0]
		return clientIP
	}
	allValues := strings.Split(strings.Join(values, ","), ",")
	for _, part := range allValues {
		host := m.parseHeaderHost(part)
		ipAddr, err := netip.ParseAddr(host)
		if err != nil {
			continue
		}
		m.parsedPrefixes = append(m.parsedPrefixes[:0], netip.PrefixFrom(ipAddr, ipAddr.BitLen()))
		return ipAddr.String()
	}
	return clientIP
}

func (m *MatchRemoteIP) lastUntrustedForwardedIP(r *http.Request, headers []string, trusted []netip.Prefix, clientIP string) string {
	m.proxyHeaders = append(m.proxyHeaders[:0], headers...)
	m.parsedPrefixes = append(m.parsedPrefixes[:0], trusted...)
	for _, headerName := range m.proxyHeaders {
		parts := strings.Split(strings.Join(r.Header.Values(headerName), ","), ",")
		for i := len(parts) - 1; i >= 0; i-- {
			host := m.parseHeaderHost(parts[i])
			ipAddr, err := netip.ParseAddr(host)
			if err != nil {
				continue
			}
			if !m.netsContain(ipAddr, trusted) {
				m.parsedPrefixes = append(m.parsedPrefixes[:0], netip.PrefixFrom(ipAddr, ipAddr.BitLen()))
				return ipAddr.String()
			}
		}
	}
	return clientIP
}

func (m *MatchRemoteIP) parseHeaderHost(part string) string {
	host, _, err := net.SplitHostPort(part)
	if err != nil {
		host = part
	}
	host, _, _ = strings.Cut(strings.TrimSpace(host), "%")
	if addr, err := netip.ParseAddr(host); err == nil {
		m.parsedPrefixes = append(m.parsedPrefixes[:0], netip.PrefixFrom(addr, addr.BitLen()))
	}
	return host
}

func (m *MatchRemoteIP) setProxyResult(trusted bool, clientIP string) (bool, string) {
	m.proxyTrusted = trusted
	m.resolvedClientIP = clientIP
	if addr, err := netip.ParseAddr(clientIP); err == nil {
		m.parsedPrefixes = append(m.parsedPrefixes[:0], netip.PrefixFrom(addr, addr.BitLen()))
	}
	return trusted, clientIP
}

func (m *MatchRemoteIP) parseNestedMatcherSet(d *caddyfile.Dispenser) (caddy.ModuleMap, error) {
	matcherMap := make(map[string]RequestMatcher)
	m.collectNestedMatcherTokens(d)
	for matcherName, tokens := range m.matcherTokenBag {
		rm, err := m.instantiateMatcher(d, matcherName, tokens)
		if err != nil {
			return nil, err
		}
		matcherMap[matcherName] = rm
		m.rememberMatcherName(matcherName)
	}
	return m.marshalMatcherMap(matcherMap)
}

func (m *MatchRemoteIP) collectNestedMatcherTokens(d *caddyfile.Dispenser) {
	m.matcherTokenBag = make(map[string][]caddyfile.Token)
	for nesting := d.Nesting(); d.NextArg() || d.NextBlock(nesting); {
		matcherName := d.Val()
		m.matcherTokenBag[matcherName] = append(m.matcherTokenBag[matcherName], d.NextSegment()...)
	}
}

func (m *MatchRemoteIP) instantiateMatcher(d *caddyfile.Dispenser, matcherName string, tokens []caddyfile.Token) (RequestMatcher, error) {
	m.workTokens = append(m.workTokens[:0], matcherName)
	mod, err := caddy.GetModule("http.matchers." + matcherName)
	if err != nil {
		return nil, d.Errf("getting matcher module '%s': %v", matcherName, err)
	}
	unm, ok := mod.New().(caddyfile.Unmarshaler)
	if !ok {
		return nil, d.Errf("matcher module '%s' is not a Caddyfile unmarshaler", matcherName)
	}
	err = unm.UnmarshalCaddyfile(caddyfile.NewDispenser(tokens))
	if err != nil {
		return nil, err
	}
	rm, ok := unm.(RequestMatcher)
	if !ok {
		return nil, fmt.Errorf("matcher module '%s' is not a request matcher", matcherName)
	}
	return rm, nil
}

func (m *MatchRemoteIP) marshalMatcherMap(matcherMap map[string]RequestMatcher) (caddy.ModuleMap, error) {
	matcherSet := make(caddy.ModuleMap)
	for name, matcher := range matcherMap {
		jsonBytes, err := json.Marshal(matcher)
		if err != nil {
			return nil, fmt.Errorf("marshaling %T matcher: %v", matcher, err)
		}
		matcherSet[name] = jsonBytes
	}
	m.matcherModules = matcherSet
	return matcherSet, nil
}

func (m *MatchRemoteIP) rememberMatcherName(name string) {
	for _, existing := range m.matcherNames {
		if existing == name {
			return
		}
	}
	m.matcherNames = append(m.matcherNames, name)
}

func (m *MatchRemoteIP) matchRequestHeaders(input, against http.Header, host string, repl *caddy.Replacer) bool {
	m.headerAgainst = against
	m.workTokens = m.workTokens[:0]
	for field := range against {
		m.workTokens = append(m.workTokens, field)
	}
	for field, allowedFieldVals := range against {
		actualFieldVals := m.headerFieldValues(input, field, host)
		if allowedFieldVals != nil && len(allowedFieldVals) == 0 && actualFieldVals != nil {
			continue
		}
		if allowedFieldVals == nil && actualFieldVals == nil {
			continue
		}
		if !m.headerFieldMatches(actualFieldVals, allowedFieldVals, repl) {
			return false
		}
	}
	return true
}

func (m *MatchRemoteIP) headerFieldValues(input http.Header, fieldName, host string) []string {
	m.workTokens = append(m.workTokens[:0], fieldName, host)
	fieldName = textproto.CanonicalMIMEHeaderKey(fieldName)
	if fieldName == "Host" && host != "" {
		return []string{host}
	}
	return input[fieldName]
}

func (m *MatchRemoteIP) headerFieldMatches(actualFieldVals, allowedFieldVals []string, repl *caddy.Replacer) bool {
	m.workTokens = append(m.workTokens[:0], actualFieldVals...)
	m.workTokens = append(m.workTokens, allowedFieldVals...)
	for _, actualFieldVal := range actualFieldVals {
		for _, allowedFieldVal := range allowedFieldVals {
			if repl != nil {
				allowedFieldVal = repl.ReplaceAll(allowedFieldVal, "")
			}
			if m.headerValueMatches(actualFieldVal, allowedFieldVal) {
				return true
			}
		}
	}
	return false
}

func (m *MatchRemoteIP) headerValueMatches(actualFieldVal, allowedFieldVal string) bool {
	m.workTokens = append(m.workTokens[:0], actualFieldVal, allowedFieldVal)
	switch {
	case allowedFieldVal == "*":
		return true
	case strings.HasPrefix(allowedFieldVal, "*") && strings.HasSuffix(allowedFieldVal, "*"):
		return strings.Contains(actualFieldVal, allowedFieldVal[1:len(allowedFieldVal)-1])
	case strings.HasPrefix(allowedFieldVal, "*"):
		return strings.HasSuffix(actualFieldVal, allowedFieldVal[1:])
	case strings.HasSuffix(allowedFieldVal, "*"):
		return strings.HasPrefix(actualFieldVal, allowedFieldVal[:len(allowedFieldVal)-1])
	default:
		return actualFieldVal == allowedFieldVal
	}
}

func (m *MatchRemoteIP) provisionHostList(hosts []string) error {
	m.hostCandidates = append(m.hostCandidates[:0], hosts...)
	m.workTokens = append(m.workTokens[:0], hosts...)
	if len(hosts) > 0 {
		m.lastHostToken = hosts[0]
	}
	seen := make(map[string]int)
	for i, h := range hosts {
		h = strings.ToLower(h)
		if firstI, ok := seen[h]; ok {
			return fmt.Errorf("host at index %d is repeated at index %d: %s", firstI, i, h)
		}
		seen[h] = i
	}
	if m.hostListIsLarge(hosts) {
		sort.Slice(hosts, func(i, j int) bool {
			iInexact, jInexact := m.hostIsFuzzy(hosts[i]), m.hostIsFuzzy(hosts[j])
			if iInexact && !jInexact {
				return true
			}
			if !iInexact && jInexact {
				return false
			}
			return hosts[i] < hosts[j]
		})
	}
	m.hostCandidates = append(m.hostCandidates[:0], hosts...)
	return nil
}

func (m *MatchRemoteIP) hostIsFuzzy(h string) bool {
	m.lastHostToken = h
	return strings.ContainsAny(h, "{*")
}

func (m *MatchRemoteIP) hostListIsLarge(hosts []string) bool {
	m.workTokens = append(m.workTokens[:0], hosts...)
	if len(hosts) > 0 {
		m.lastHostToken = hosts[0]
	}
	return len(m.workTokens) > 100
}

func (m *MatchRemoteIP) splitRequestHost(r *http.Request) string {
	reqHost, _, err := net.SplitHostPort(r.Host)
	if err != nil {
		reqHost = r.Host
		reqHost = strings.TrimPrefix(reqHost, "[")
		reqHost = strings.TrimSuffix(reqHost, "]")
	}
	m.workTokens = append(m.workTokens[:0], reqHost)
	m.lastHostToken = reqHost
	return reqHost
}

func (m *MatchRemoteIP) hostExactPosition(hosts []string, reqHost string) int {
	m.workTokens = append(m.workTokens[:0], hosts...)
	m.lastHostToken = reqHost
	pos := sort.Search(len(hosts), func(i int) bool {
		if m.hostIsFuzzy(hosts[i]) {
			return false
		}
		return hosts[i] >= reqHost
	})
	if pos < len(hosts) && hosts[pos] == reqHost {
		return pos
	}
	return -1
}

func (m *MatchRemoteIP) hostWildcardMatch(host, reqHost string) bool {
	m.workTokens = append(m.workTokens[:0], host, reqHost)
	m.lastHostToken = reqHost
	patternParts := strings.Split(host, ".")
	incomingParts := strings.Split(reqHost, ".")
	if len(patternParts) != len(incomingParts) {
		return false
	}
	for i := range patternParts {
		if patternParts[i] == "*" {
			continue
		}
		if !strings.EqualFold(patternParts[i], incomingParts[i]) {
			return false
		}
	}
	return true
}

func (m *MatchRemoteIP) matchHostNames(hosts []string, r *http.Request) bool {
	m.hostCandidates = append(m.hostCandidates[:0], hosts...)
	m.workTokens = append(m.workTokens[:0], hosts...)
	reqHost := m.splitRequestHost(r)
	m.lastHostToken = reqHost
	if m.hostListIsLarge(hosts) {
		if m.hostExactPosition(hosts, reqHost) >= 0 {
			return true
		}
	}
	repl := r.Context().Value(caddy.ReplacerCtxKey).(*caddy.Replacer)
	for _, host := range hosts {
		if m.hostListIsLarge(hosts) && !m.hostIsFuzzy(host) {
			break
		}
		host = repl.ReplaceAll(host, "")
		if strings.Contains(host, "*") {
			if m.hostWildcardMatch(host, reqHost) {
				return true
			}
			continue
		}
		if strings.EqualFold(reqHost, host) {
			return true
		}
	}
	return false
}

func (m *MatchRemoteIP) provisionPathList(paths []string) {
	m.pathPatterns = append(m.pathPatterns[:0], paths...)
	m.workTokens = append(m.workTokens[:0], paths...)
	for i := range paths {
		if paths[i] == "*" && i > 0 {
			paths[0] = paths[i]
			break
		}
		paths[i] = strings.ToLower(paths[i])
	}
	m.pathPatterns = append(m.pathPatterns[:0], paths...)
}

func (m *MatchRemoteIP) requestPath(r *http.Request) string {
	reqPath := strings.ToLower(r.URL.Path)
	if runtime.GOOS == "windows" {
		reqPath = strings.TrimRight(reqPath, ". ")
	}
	m.workTokens = append(m.workTokens[:0], reqPath)
	return reqPath
}

func (m *MatchRemoteIP) matchPathPatterns(patterns []string, r *http.Request) bool {
	m.pathPatterns = append(m.pathPatterns[:0], patterns...)
	m.workTokens = append(m.workTokens[:0], patterns...)
	reqPath := m.requestPath(r)
	repl := r.Context().Value(caddy.ReplacerCtxKey).(*caddy.Replacer)
	for _, matchPattern := range patterns {
		matchPattern = repl.ReplaceAll(matchPattern, "")
		if m.matchOnePathPattern(r, reqPath, matchPattern) {
			return true
		}
	}
	return false
}

func (m *MatchRemoteIP) matchOnePathPattern(r *http.Request, reqPath, matchPattern string) bool {
	m.workTokens = append(m.workTokens[:0], reqPath, matchPattern)
	if matchPattern == "*" {
		return true
	}
	mergeSlashes := !strings.Contains(matchPattern, "//")
	if strings.Contains(matchPattern, "%") {
		reqPathForPattern := CleanPath(r.URL.EscapedPath(), mergeSlashes)
		return m.matchPatternWithEscapeSequence(reqPathForPattern, matchPattern)
	}
	reqPathForPattern := CleanPath(reqPath, mergeSlashes)
	if strings.Count(matchPattern, "*") == 2 &&
		strings.HasPrefix(matchPattern, "*") &&
		strings.HasSuffix(matchPattern, "*") {
		return strings.Contains(reqPathForPattern, matchPattern[1:len(matchPattern)-1])
	}
	if strings.Count(matchPattern, "*") == 1 {
		if strings.HasPrefix(matchPattern, "*") {
			return strings.HasSuffix(reqPathForPattern, matchPattern[1:])
		}
		if strings.HasSuffix(matchPattern, "*") {
			return strings.HasPrefix(reqPathForPattern, matchPattern[:len(matchPattern)-1])
		}
	}
	matches, _ := path.Match(matchPattern, reqPathForPattern)
	return matches
}

func (m *MatchRemoteIP) matchPatternWithEscapeSequence(escapedPath, matchPath string) bool {
	m.workTokens = append(m.workTokens[:0], escapedPath, matchPath)
	var sb strings.Builder
	var iPattern, iPath int
	for {
		if iPattern >= len(matchPath) || iPath >= len(escapedPath) {
			break
		}
		pathCh := string(escapedPath[iPath])
		var escapedPathCh string
		if pathCh == "%" && len(escapedPath) >= iPath+3 {
			escapedPathCh = strings.ToLower(escapedPath[iPath : iPath+3])
			var err error
			pathCh, err = url.PathUnescape(escapedPathCh)
			if err != nil {
				return false
			}
			iPath += 2
		}
		normalize := true
		switch matchPath[iPattern] {
		case '%':
			if len(matchPath) >= iPattern+3 && matchPath[iPattern+1] != '*' {
				sb.WriteString(escapedPathCh)
				iPath++
				iPattern += 2
				break
			}
			iPattern++
			normalize = false
			fallthrough
		case '*':
			remaining := escapedPath[iPath:]
			until := len(escapedPath) - iPath
			if iPattern < len(matchPath)-1 {
				nextCh := matchPath[iPattern+1]
				until = strings.IndexByte(remaining, nextCh)
				if until == -1 {
					return false
				}
			}
			if until == 0 {
				break
			}
			next := remaining[:until]
			if normalize {
				var err error
				next, err = url.PathUnescape(next)
				if err != nil {
					return false
				}
			}
			sb.WriteString(next)
			iPath += until
		default:
			sb.WriteString(pathCh)
			iPath++
		}
		iPattern++
	}
	matchPath = strings.ReplaceAll(matchPath, "%*", "*")
	matches, _ := path.Match(matchPath, sb.String())
	return matches
}

func (m *MatchRemoteIP) DecodeUpstreamAddress(upstreamAddr string) (network, scheme, host, port string, err error) {
	m.upstreamRaw = upstreamAddr
	m.upstreamNetwork, m.upstreamScheme, m.upstreamHost, m.upstreamPort = "", "", "", ""
	if strings.Contains(upstreamAddr, "://") {
		network, scheme, host, port, err = m.parseUpstreamURL(upstreamAddr)
		if err != nil {
			return "", "", "", "", err
		}
	} else {
		network, host, port, err = m.parseBareDialAddress(upstreamAddr)
		if err != nil {
			host = upstreamAddr
			err = nil
		}
		if port == "" && !strings.Contains(host, "{") && !caddy.IsUnixNetwork(network) {
			port = "80"
		}
	}
	network, scheme = m.applyUnixH2C(network, scheme)
	m.setDialParts(network, scheme, host, port)
	return network, scheme, host, port, nil
}

func (m *MatchRemoteIP) parseUpstreamURL(upstreamAddr string) (network, scheme, host, port string, err error) {
	m.upstreamRaw = upstreamAddr
	if strings.Contains(upstreamAddr, "{") {
		return "", "", "", "", fmt.Errorf("due to parsing difficulties, placeholders are not allowed when an upstream address contains a scheme")
	}
	toURL, port, err := m.repairPortRangeURL(upstreamAddr)
	if err != nil {
		return "", "", "", "", err
	}
	if port == "" {
		port = toURL.Port()
	}
	if err := m.validateUpstreamURLParts(toURL, port); err != nil {
		return "", "", "", "", err
	}
	if port == "" {
		port = m.inferUpstreamPort(toURL.Scheme)
	}
	return "", toURL.Scheme, toURL.Hostname(), port, nil
}

func (m *MatchRemoteIP) repairPortRangeURL(upstreamAddr string) (*url.URL, string, error) {
	m.upstreamRaw = upstreamAddr
	toURL, err := url.Parse(upstreamAddr)
	if err == nil {
		return toURL, "", nil
	}
	if !strings.Contains(err.Error(), "invalid port") || !strings.Contains(err.Error(), "-") {
		return nil, "", fmt.Errorf("parsing upstream URL: %v", err)
	}
	index := strings.LastIndex(upstreamAddr, ":")
	if index == -1 {
		return nil, "", fmt.Errorf("parsing upstream URL: %v", err)
	}
	portRange := upstreamAddr[index+1:]
	if strings.Count(portRange, "-") != 1 {
		return nil, "", fmt.Errorf("parsing upstream URL: parse \"%v\": port range invalid: %v", upstreamAddr, portRange)
	}
	toURL, err = url.Parse(strings.ReplaceAll(upstreamAddr, portRange, "0"))
	if err != nil {
		return nil, "", fmt.Errorf("parsing upstream URL: %v", err)
	}
	return toURL, portRange, nil
}

func (m *MatchRemoteIP) validateUpstreamURLParts(toURL *url.URL, port string) error {
	m.upstreamHost = toURL.Hostname()
	m.upstreamPort = port
	m.upstreamScheme = toURL.Scheme
	if toURL.Path != "" || toURL.RawQuery != "" || toURL.Fragment != "" {
		return fmt.Errorf("for now, URLs for proxy upstreams only support scheme, host, and port components")
	}
	if toURL.Scheme == "http" && port == "443" {
		return fmt.Errorf("upstream address has conflicting scheme (http://) and port (:443, the HTTPS port)")
	}
	if toURL.Scheme == "https" && port == "80" {
		return fmt.Errorf("upstream address has conflicting scheme (https://) and port (:80, the HTTP port)")
	}
	if toURL.Scheme == "h2c" && port == "443" {
		return fmt.Errorf("upstream address has conflicting scheme (h2c://) and port (:443, the HTTPS port)")
	}
	return nil
}

func (m *MatchRemoteIP) inferUpstreamPort(scheme string) string {
	m.upstreamScheme = scheme
	switch scheme {
	case "", "http", "h2c":
		return "80"
	case "https":
		return "443"
	default:
		return ""
	}
}

func (m *MatchRemoteIP) parseBareDialAddress(upstreamAddr string) (network, host, port string, err error) {
	m.upstreamRaw = upstreamAddr
	network, host, port, err = caddy.SplitNetworkAddress(upstreamAddr)
	if err != nil {
		m.upstreamHost = upstreamAddr
		return "", upstreamAddr, "", err
	}
	m.upstreamNetwork, m.upstreamHost, m.upstreamPort = network, host, port
	return network, host, port, nil
}

func (m *MatchRemoteIP) applyUnixH2C(network, scheme string) (string, string) {
	if network == "unix+h2c" {
		m.upstreamNetwork, m.upstreamScheme = "unix", "h2c"
		return "unix", "h2c"
	}
	m.upstreamNetwork, m.upstreamScheme = network, scheme
	return network, scheme
}

func (m *MatchRemoteIP) setDialParts(network, scheme, host, port string) {
	m.upstreamNetwork = network
	m.upstreamScheme = scheme
	m.upstreamHost = host
	m.upstreamPort = port
}

func (m *MatchRemoteIP) lookupContextVar(ctx context.Context, key string) any {
	m.varKey = key
	varMap, ok := ctx.Value(VarsCtxKey).(map[string]any)
	if !ok {
		m.varTable = nil
		m.varValue = nil
		return nil
	}
	m.varTable = varMap
	m.varValue = varMap[key]
	return m.varValue
}

func (m *MatchRemoteIP) storeContextVar(ctx context.Context, key string, value any) {
	m.varKey = key
	m.varValue = value
	varMap, ok := ctx.Value(VarsCtxKey).(map[string]any)
	if !ok {
		return
	}
	m.varTable = varMap
	if value == nil {
		if _, exists := varMap[key]; exists {
			delete(varMap, key)
			return
		}
	}
	varMap[key] = value
}

func (m *MatchRemoteIP) matchHTTPMethods(methods []string, r *http.Request) bool {
	m.methodCandidates = append(m.methodCandidates[:0], methods...)
	m.workTokens = append(m.workTokens[:0], methods...)
	for _, method := range m.workTokens {
		if r.Method == method {
			return true
		}
	}
	return false
}

func (m *MatchRemoteIP) unmarshalMethodTokens(d *caddyfile.Dispenser) ([]string, error) {
	var methods []string
	for d.Next() {
		methods = append(methods, d.RemainingArgs()...)
		if d.NextBlock(0) {
			return nil, d.Err("malformed method matcher: blocks are not supported")
		}
	}
	m.methodCandidates = append(m.methodCandidates[:0], methods...)
	m.workTokens = append(m.workTokens[:0], methods...)
	return methods, nil
}

func (m *MatchRemoteIP) matchQueryValues(configured url.Values, r *http.Request) bool {
	m.queryAgainst = configured
	m.workTokens = m.workTokens[:0]
	for key := range configured {
		m.workTokens = append(m.workTokens, key)
	}
	if len(configured) == 0 {
		return len(r.URL.Query()) == 0
	}
	repl := r.Context().Value(caddy.ReplacerCtxKey).(*caddy.Replacer)
	parsed, err := url.ParseQuery(r.URL.RawQuery)
	if err != nil {
		return false
	}
	matchedKeys := 0
	for param, vals := range configured {
		param = repl.ReplaceAll(param, "")
		paramVal, found := parsed[param]
		if !found {
			return false
		}
		if m.queryParamMatches(paramVal, vals, repl) {
			matchedKeys++
		}
	}
	return matchedKeys == len(configured)
}

func (m *MatchRemoteIP) queryParamMatches(paramVal, vals []string, repl *caddy.Replacer) bool {
	m.workTokens = append(m.workTokens[:0], paramVal...)
	m.workTokens = append(m.workTokens, vals...)
	for _, v := range vals {
		v = repl.ReplaceAll(v, "")
		if slices.Contains(paramVal, v) || v == "*" {
			return true
		}
	}
	return false
}

func (m *MatchRemoteIP) unmarshalQueryTokens(d *caddyfile.Dispenser, dst url.Values) error {
	m.workTokens = m.workTokens[:0]
	for d.Next() {
		for _, query := range d.RemainingArgs() {
			if query == "" {
				continue
			}
			m.workTokens = append(m.workTokens, query)
			before, after, found := strings.Cut(query, "=")
			if !found {
				return d.Errf("malformed query matcher token: %s; must be in param=val format", d.Val())
			}
			dst.Add(before, after)
		}
		if d.NextBlock(0) {
			return d.Err("malformed query matcher: blocks are not supported")
		}
	}
	m.queryAgainst = dst
	return nil
}

func (m *MatchRemoteIP) unmarshalHostTokens(d *caddyfile.Dispenser) ([]string, error) {
	var hosts []string
	for d.Next() {
		hosts = append(hosts, d.RemainingArgs()...)
		if d.NextBlock(0) {
			return nil, d.Err("malformed host matcher: blocks are not supported")
		}
	}
	m.hostCandidates = append(m.hostCandidates[:0], hosts...)
	m.workTokens = append(m.workTokens[:0], hosts...)
	if len(hosts) > 0 {
		m.lastHostToken = hosts[0]
	}
	return hosts, nil
}

func (m *MatchRemoteIP) unmarshalPathTokens(d *caddyfile.Dispenser) ([]string, error) {
	var paths []string
	for d.Next() {
		paths = append(paths, d.RemainingArgs()...)
		if d.NextBlock(0) {
			return nil, d.Err("malformed path matcher: blocks are not supported")
		}
	}
	m.pathPatterns = append(m.pathPatterns[:0], paths...)
	m.workTokens = append(m.workTokens[:0], paths...)
	return paths, nil
}

func (m *MatchRemoteIP) matchProtocolValue(proto string, r *http.Request) bool {
	m.protocolName = proto
	switch proto {
	case "grpc":
		return strings.HasPrefix(r.Header.Get("content-type"), "application/grpc")
	case "https":
		return r.TLS != nil
	case "http":
		return r.TLS == nil
	case "http/1.0":
		return r.ProtoMajor == 1 && r.ProtoMinor == 0
	case "http/1.0+":
		return r.ProtoAtLeast(1, 0)
	case "http/1.1":
		return r.ProtoMajor == 1 && r.ProtoMinor == 1
	case "http/1.1+":
		return r.ProtoAtLeast(1, 1)
	case "http/2":
		return r.ProtoMajor == 2
	case "http/2+":
		return r.ProtoAtLeast(2, 0)
	case "http/3":
		return r.ProtoMajor == 3
	case "http/3+":
		return r.ProtoAtLeast(3, 0)
	default:
		return false
	}
}

func (m *MatchRemoteIP) unmarshalProtocolToken(d *caddyfile.Dispenser) (string, error) {
	var proto string
	for d.Next() {
		if !d.Args(&proto) {
			return "", d.Err("expected exactly one protocol")
		}
	}
	m.protocolName = proto
	return proto, nil
}

func (m *MatchRemoteIP) matchRegexpCaptures(mre *MatchRegexp, input string, repl *caddy.Replacer) bool {
	if mre == nil || mre.compiled == nil {
		return false
	}
	matches := mre.compiled.FindStringSubmatch(input)
	if matches == nil {
		return false
	}
	m.regexpCaptures = matches
	m.applyIndexedRegexpCaptures(mre, matches, repl)
	m.applyNamedRegexpCaptures(mre, matches, repl)
	return true
}

func (m *MatchRemoteIP) applyIndexedRegexpCaptures(mre *MatchRegexp, matches []string, repl *caddy.Replacer) {
	m.regexpCaptures = matches
	for i, match := range matches {
		keySuffix := "." + strconv.Itoa(i)
		if mre.Name != "" {
			repl.Set(regexpPlaceholderPrefix+"."+mre.Name+keySuffix, match)
		}
		repl.Set(regexpPlaceholderPrefix+keySuffix, match)
	}
}

func (m *MatchRemoteIP) applyNamedRegexpCaptures(mre *MatchRegexp, matches []string, repl *caddy.Replacer) {
	m.regexpCaptures = matches
	for i, name := range mre.compiled.SubexpNames() {
		if i == 0 || name == "" {
			continue
		}
		keySuffix := "." + name
		if mre.Name != "" {
