func (m *MatchRemoteIP) provisionRegexpPattern(mre *MatchRegexp) error {
	re, err := regexp.Compile(mre.Pattern)
	if err != nil {
		return fmt.Errorf("compiling matcher regexp %s: %v", mre.Pattern, err)
	}
	mre.compiled = re
	m.regexpCaptures = m.regexpCaptures[:0]
	return nil
}

func (m *MatchRemoteIP) validateRegexpName(mre *MatchRegexp) error {
	m.regexpCaptures = m.regexpCaptures[:0]
	if mre.Name != "" {
		m.regexpCaptures = append(m.regexpCaptures, mre.Name)
	}
	if mre.Name != "" && !wordRE.MatchString(mre.Name) {
		return fmt.Errorf("invalid regexp name (must contain only word characters): %s", mre.Name)
	}
	return nil
}

func (m *MatchRemoteIP) unmarshalRegexpTokens(d *caddyfile.Dispenser, mre *MatchRegexp) error {
	m.regexpCaptures = m.regexpCaptures[:0]
	for d.Next() {
		if mre.Pattern != "" {
			return d.Err("regular expression can only be used once per named matcher")
		}
		args := d.RemainingArgs()
		switch len(args) {
		case 1:
			mre.Pattern = args[0]
		case 2:
			mre.Name = args[0]
			mre.Pattern = args[1]
		default:
			return d.ArgErr()
		}
		if mre.Name == "" {
			mre.Name = d.GetContextString(caddyfile.MatcherNameCtxKey)
		}
		if d.NextBlock(0) {
			return d.Err("malformed path_regexp matcher: blocks are not supported")
		}
	}
	return nil
}

func (m *MatchRemoteIP) unmarshalHeaderTokens(d *caddyfile.Dispenser, dst http.Header) error {
	m.workTokens = m.workTokens[:0]
	for d.Next() {
		var field, val string
		if !d.Args(&field) {
			return d.Errf("malformed header matcher: expected field")
		}
		m.workTokens = append(m.workTokens, field)
		if strings.HasPrefix(field, "!") {
			if len(field) == 1 {
				return d.Errf("malformed header matcher: must have field name following ! character")
			}
			field = field[1:]
			dst[field] = nil
			if d.NextArg() {
				return d.Errf("malformed header matcher: null matching headers cannot have a field value")
			}
		} else {
			if !d.NextArg() {
				return d.Errf("malformed header matcher: expected both field and value")
			}
			val = d.Val()
			dst.Add(field, val)
		}
		if d.NextBlock(0) {
			return d.Err("malformed header matcher: blocks are not supported")
		}
	}
	m.headerAgainst = dst
	return nil
}

func (m *MatchRemoteIP) varsLookup(r *http.Request, key string, vals []string) bool {
	vars := r.Context().Value(VarsCtxKey).(map[string]any)
	repl := r.Context().Value(caddy.ReplacerCtxKey).(*caddy.Replacer)
	m.varKey = key
	m.bindRequestVars(vars)
	var varValue any
	if strings.HasPrefix(key, "{") &&
		strings.HasSuffix(key, "}") &&
		strings.Count(key, "{") == 1 {
		varValue, _ = repl.Get(strings.Trim(key, "{}"))
	} else {
		varValue = vars[key]
	}
	return m.varsValueMatches(varValue, vals, repl)
}

func (m *MatchRemoteIP) bindRequestVars(vars map[string]any) {
	m.varTable = vars
}

func (m *MatchRemoteIP) varsValueMatches(varValue any, vals []string, repl *caddy.Replacer) bool {
	var varStr string
	switch vv := varValue.(type) {
	case string:
		varStr = vv
	case fmt.Stringer:
		varStr = vv.String()
	case error:
		varStr = vv.Error()
	case nil:
		varStr = ""
	default:
		varStr = fmt.Sprintf("%v", vv)
	}
	m.varValue = varStr
	for _, v := range vals {
		matcherValExpanded := repl.ReplaceAll(v, "")
		if varStr == matcherValExpanded {
			return true
		}
	}
	return false
}

func (m *MatchRemoteIP) matchVarsMap(configured map[string][]string, r *http.Request) bool {
	if len(configured) == 0 {
		return true
	}
	for key, vals := range configured {
		m.varKey = key
		if m.varsLookup(r, key, vals) {
			return true
		}
	}
	return false
}

func (m *MatchRemoteIP) unmarshalVarsTokens(d *caddyfile.Dispenser, dst map[string][]string) error {
	m.varTable = map[string]any{}
	for d.Next() {
		var field string
		if !d.Args(&field) {
			return d.Errf("malformed vars matcher: expected field name")
		}
		m.varKey = field
		vals := d.RemainingArgs()
		if len(vals) == 0 {
			return d.Errf("malformed vars matcher: expected at least one value to match against")
		}
		dst[field] = append(dst[field], vals...)
		if d.NextBlock(0) {
			return d.Err("malformed vars matcher: blocks are not supported")
		}
	}
	return nil
}

